parameters.jsCode:
// Calculo sobre un unico item (sin bucles de arreglos)
const item = $input.first().json;

// 1. Semaforo nutricional individual por 100g
// Azucar: bajo < 5g, medio 5 a 22.5g, alto > 22.5g
const sugarTag = item.sugars_100g > 22.5 ? 'alto' : (item.sugars_100g < 5 ? 'bajo' : 'medio');
// Sal: alto > 1.5g
const saltTag = item.salt_100g > 1.5 ? 'alto' : 'bajo';
// Grasa: alto > 17.5g
const fatTag = item.fat_100g > 17.5 ? 'alto' : 'bajo';

// 2. Puntuacion de Preocupacion (Concern Score: 0 a 3)
let highCount = 0;
if (sugarTag === 'alto') highCount++;
if (saltTag === 'alto') highCount++;
if (fatTag === 'alto') highCount++;
const concernScore = highCount;

// 3. Lectura de Semaforo
let trafficVerdict = 'saludable';
if (concernScore === 1) {
  trafficVerdict = 'moderado';
} else if (concernScore >= 2) {
  trafficVerdict = 'no saludable';
}

// 4. Lectura de Nutri-Score
const score = item.nutriscore_grade;
let nutriVerdict = null;
if (['a', 'b'].includes(score)) {
  nutriVerdict = 'saludable';
} else if (score === 'c') {
  nutriVerdict = 'moderado';
} else if (['d', 'e'].includes(score)) {
  nutriVerdict = 'no saludable';
}

// 5. Veredicto del Peor Caso
const ranking = { 'saludable': 1, 'moderado': 2, 'no saludable': 3 };
let finalVerdict = trafficVerdict;

if (nutriVerdict && ranking[nutriVerdict] > ranking[trafficVerdict]) {
  finalVerdict = nutriVerdict;
}

return [{
  json: {
    ...item,
    sugarTag,
    saltTag,
    fatTag,
    concernScore,
    trafficVerdict,
    nutriVerdict: nutriVerdict || 'desconocido',
    finalVerdict
  }
}];
